import React from 'react';
import type { ReactNode } from 'react';
import { cn } from '../../internal/cn';

/* ============================================
 * MultiSelection (Checkbox 패턴)
 * Figma Source: 03_Components > Multi Selection (Checkbox 패턴)
 *
 * 선택 가능한 checkbox 행 목록(다중 선택). SingleSelection 의 체크박스 버전.
 * 행 = checkbox + 라벨 + 우측 메타(description), 행 컨테이너에 선택 스타일.
 *
 * Figma 토큰:
 *   default:  border gray-200 / 라벨 Regular gray-950 / 메타 gray-600 / checkbox 빈 박스(gray-300)
 *   selected: bg info-subtle + border info(#2563eb) / 라벨 SemiBold / checkbox primary+체크
 *   disabled: border gray-200 / 라벨·메타 gray-400
 *   행: px-16 py-12 rounded-8, checkbox-내용 gap 12, 내용(라벨↔메타) justify-between
 * ============================================ */

export interface MultiSelectionOption {
  value: string;
  label: string;
  /** 우측 메타 텍스트 (예: "담당: 서울 전체") */
  description?: ReactNode;
  disabled?: boolean;
}

export interface MultiSelectionProps {
  name?: string;
  options: MultiSelectionOption[];
  value?: string[];
  onChange?: (value: string[]) => void;
  className?: string;
  'data-testid'?: string;
}

export const MultiSelection: React.FC<MultiSelectionProps> = ({
  name,
  options,
  value = [],
  onChange,
  className,
  'data-testid': dataTestId,
}) => {
  const toggle = (v: string) => {
    onChange?.(value.includes(v) ? value.filter((x) => x !== v) : [...value, v]);
  };

  return (
    <div className={cn('flex flex-col gap-2', className)} data-testid={dataTestId}>
      {options.map((opt) => {
        const selected = value.includes(opt.value);
        const disabled = !!opt.disabled;
        return (
          <label
            key={opt.value}
            className={cn(
              'flex items-center gap-3 px-4 py-3 rounded-[8px] border transition-colors',
              disabled
                ? 'border-border cursor-not-allowed'
                : selected
                  ? 'border-info bg-info-subtle cursor-pointer'
                  : 'border-border hover:bg-surface-muted cursor-pointer'
            )}
          >
            <input
              type="checkbox"
              name={name}
              value={opt.value}
              checked={selected}
              disabled={disabled}
              onChange={() => !disabled && toggle(opt.value)}
              className="peer sr-only"
            />
            {/* checkbox 박스 (Checkbox 컴포넌트와 동일 비주얼) */}
            <span
              aria-hidden="true"
              className={cn(
                'relative inline-flex items-center justify-center w-[18px] h-[18px] rounded-[4px] border bg-surface flex-shrink-0 transition-colors',
                selected ? 'bg-primary border-primary' : 'border-border-hover',
                'peer-focus-visible:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]'
              )}
            >
              {selected && (
                <svg width="14" height="14" viewBox="0 0 14 14" fill="none" className="text-white">
                  <path d="M3 7L5.5 9.5L11 4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              )}
            </span>
            {/* 내용: 라벨 ↔ 메타 */}
            <span className="flex flex-1 min-w-0 items-start justify-between gap-2">
              <span
                className={cn(
                  selected ? 'text-base-semibold' : 'text-base-regular',
                  disabled ? 'text-gray-400' : 'text-gray-950'
                )}
              >
                {opt.label}
              </span>
              {opt.description != null && (
                <span className={cn('text-base-regular', disabled ? 'text-gray-400' : 'text-gray-600')}>
                  {opt.description}
                </span>
              )}
            </span>
          </label>
        );
      })}
    </div>
  );
};

MultiSelection.displayName = 'MultiSelection';
