import React from 'react';
import type { TabsProps } from './Tabs.types';

/* ============================================
 * Tabs
 * Figma Source: 03_Components > Tabs (Tabs-A 48px=line / Tabs-B 40px=contained)
 * (props 는 staff Tabs 와 동일 — drop-in 대체용)
 *
 * Variants:
 *   line       (Tabs-A, 48px): 하단 baseline + active 2px primary underline
 *   contained  (Tabs-B, 40px): bg gray-100 컨테이너, active 흰 카드 + border-gray-50 + shadow
 *
 * Figma 토큰:
 *   text 16px Medium(inactive)/SemiBold(active) · inactive gray-600 · active gray-950
 *   badge 12px Medium · inactive bg gray-200 text gray-400 · active bg primary text white
 *   (Figma disabled=gray-600이나 UX 구분 위해 gray-400+opacity 유지)
 * ============================================ */

interface VariantStyle {
  container: string;
  tab: { base: string; active: string; inactive: string; disabled: string };
  badge: { active: string; inactive: string };
}

const VARIANT_STYLES: Record<NonNullable<TabsProps['variant']>, VariantStyle> = {
  line: {
    container:
      'relative after:absolute after:left-0 after:right-0 after:bottom-0 after:h-0.5 after:bg-border after:pointer-events-none',
    tab: {
      base: 'h-12 relative',
      active:
        'text-lg-semibold text-gray-950 after:absolute after:left-0 after:right-0 after:bottom-0 after:h-0.5 after:bg-primary after:z-10',
      inactive: 'text-lg-medium text-gray-600 hover:text-gray-950 cursor-pointer',
      disabled: 'text-lg-medium text-gray-400 cursor-not-allowed opacity-50',
    },
    badge: {
      active: 'bg-primary text-white',
      inactive: 'bg-gray-200 text-gray-400',
    },
  },
  contained: {
    container: 'h-12 bg-gray-50 rounded-[8px] p-1',
    tab: {
      base: 'h-full',
      active:
        'text-lg-semibold bg-surface text-gray-950 border border-gray-50 rounded-[6px] shadow-[0_1px_1px_rgba(0,0,0,0.05)]',
      inactive: 'text-lg-medium text-gray-600 hover:text-gray-950 cursor-pointer',
      disabled: 'text-lg-medium text-gray-400 cursor-not-allowed opacity-50',
    },
    badge: {
      active: 'bg-primary text-white',
      inactive: 'bg-gray-200 text-gray-400',
    },
  },
};

const TAB_BASE =
  'relative inline-flex items-center gap-2 whitespace-nowrap px-4 py-2 ' +
  'transition-colors duration-150 font-sans ' +
  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30 focus-visible:ring-inset';

const BADGE_BASE =
  'inline-flex items-center justify-center min-w-5 h-5 px-2 py-0.5 rounded-full text-xs-medium leading-none';

export const Tabs: React.FC<TabsProps> = ({
  items,
  activeKey,
  onChange,
  variant = 'line',
  className,
  'data-testid': dataTestId,
}) => {
  const styles = VARIANT_STYLES[variant];

  return (
    <div
      className={['flex overflow-x-auto overflow-y-hidden', styles.container, className]
        .filter(Boolean)
        .join(' ')}
      role="tablist"
      data-testid={dataTestId}
    >
      {items.map((tab) => {
        const isActive = activeKey === tab.key;
        const isDisabled = !!tab.disabled;
        const tabState = isActive
          ? styles.tab.active
          : isDisabled
            ? styles.tab.disabled
            : styles.tab.inactive;
        const badgeState = isActive ? styles.badge.active : styles.badge.inactive;

        return (
          <button
            key={tab.key}
            role="tab"
            aria-selected={isActive}
            disabled={isDisabled}
            onClick={() => !isDisabled && onChange(tab.key)}
            className={[TAB_BASE, styles.tab.base, tabState].join(' ')}
          >
            {tab.icon && (
              <span aria-hidden="true" className="flex items-center">
                {tab.icon}
              </span>
            )}
            {tab.label}
            {tab.badge != null && (
              <span className={[BADGE_BASE, badgeState].join(' ')}>{tab.badge}</span>
            )}
          </button>
        );
      })}
    </div>
  );
};

Tabs.displayName = 'Tabs';
