import React from 'react';
import type { ReactNode } from 'react';
import { cn } from '../../internal/cn';

/* ============================================
 * ModalSubtitle
 * Figma Source: modal-subtitle
 *
 * 모달 내 섹션 서브 타이틀 — (아이콘) + 타이틀(17 Medium) + (· 필수) 하단 border.
 *
 * Figma 토큰:
 *   컨테이너: border-b gray-200, pt-8 pb-16, gap 8, items-center
 *   아이콘 24 + 타이틀 gap 4 · 타이틀 text-inner-tab(17 Medium) gray-950
 *   필수 표시: "· 필수" 13 Medium success(#16a34a)
 * ============================================ */

export interface ModalSubtitleProps {
  /** 좌측 아이콘 (예: <Icon name="..." size={24} />) */
  icon?: ReactNode;
  /** 서브 타이틀 텍스트 */
  children: ReactNode;
  /** "· 필수" 표시 (success 색) */
  required?: boolean;
  /** 필수 대신 커스텀 힌트 (색은 success) */
  hint?: ReactNode;
  className?: string;
}

export const ModalSubtitle: React.FC<ModalSubtitleProps> = ({
  icon,
  children,
  required = false,
  hint,
  className,
}) => {
  return (
    <div className={cn('flex w-full items-center gap-2 border-b border-border pt-2 pb-4', className)}>
      <div className="flex items-center gap-1">
        {icon && <span className="flex text-gray-950">{icon}</span>}
        <span className="text-inner-tab text-gray-950">{children}</span>
      </div>
      {(hint ?? required) && (
        <span className="text-sm-medium text-success">{hint ?? '· 필수'}</span>
      )}
    </div>
  );
};

ModalSubtitle.displayName = 'ModalSubtitle';
