import React from 'react';
import { Icon } from '../Icon';

/* ═══════════════════════════════════════
   Component: AdminLNB
   Figma Source: 06_LNB_GNB > LNB Specifications
   Role: Left Navigation Bar (좌측 사이드바)
   ═══════════════════════════════════════
   Specs:
     Width: 210px (--lnb-width)
     Height: 100vh
     Position: fixed
     Background: --nav-bg (#263949)
     Menu Item Height: 48px
     Sub Item Height: 48px
     Accent Bar: 4px (Active 좌측)
   ═══════════════════════════════════════ */

export interface LNBSubItem {
  id: string;
  label: string;
}

export interface LNBMenuItem {
  id: string;
  label: string;
  children?: LNBSubItem[];
}

export interface AdminLNBProps {
  /** 로고 텍스트 */
  logoText?: string;
  /** 사용자 이름 */
  userName?: string;
  /** 메뉴 구조 (children 포함) */
  menuItems: LNBMenuItem[];
  /** 활성화된 메뉴 ID */
  activeMenuId?: string;
  /** 활성화된 서브메뉴 ID */
  activeSubMenuId?: string;
  /** 확장된 메뉴 ID 목록 */
  expandedMenuIds?: string[];
  /** 메뉴 클릭 핸들러 */
  onMenuClick?: (menuId: string) => void;
  /** 서브메뉴 클릭 핸들러 */
  onSubMenuClick?: (menuId: string, subMenuId: string) => void;
  /** 사용자 정보 클릭 (프로필 수정) */
  onUserClick?: () => void;
  /** 로그아웃 메뉴 표시 여부 */
  showLogout?: boolean;
  /** 로그아웃 클릭 핸들러 */
  onLogoutClick?: () => void;
  /** 접힘 상태 (60px) */
  collapsed?: boolean;
}

export const AdminLNB: React.FC<AdminLNBProps> = ({
  logoText = 'IMAS',
  userName,
  menuItems,
  activeMenuId,
  activeSubMenuId,
  expandedMenuIds = [],
  onMenuClick,
  onSubMenuClick,
  onUserClick,
  showLogout = true,
  onLogoutClick,
  collapsed = false,
}) => {
  return (
    <nav
      className={[
        'fixed top-0 z-[110] flex flex-col overflow-y-auto overflow-x-hidden bg-nav-bg',
        'h-screen w-lnb transition-[left] duration-200 ease-in-out',
        collapsed ? '-left-lnb' : 'left-0',
      ].join(' ')}
      role="navigation"
      aria-label="사이드 네비게이션"
    >
      {/* Logo + User — Figma: py-24, center, no border, gap-8 */}
      <div className="flex flex-col items-center gap-2 py-6">
        <div className="text-lnb-logo text-white text-center tracking-[-0.28px]">
          {logoText}
        </div>
        {userName && !collapsed && (
          <button
            type="button"
            className="flex items-center gap-1 text-base-medium font-semibold text-white tracking-[-0.14px] bg-transparent border-none cursor-pointer p-0 hover:opacity-80 transition-opacity"
            onClick={onUserClick}
          >
            {userName}
            <Icon name="edit_square" size={16} decorative />
          </button>
        )}
      </div>

      {/* Menu */}
      <div className="relative flex flex-1 flex-col py-2">
        {menuItems.map((item) => {
          const isActive = item.id === activeMenuId;
          const isExpanded = expandedMenuIds.includes(item.id);
          const hasChildren = item.children && item.children.length > 0;

          return (
            <div key={item.id} className="relative">
              {/* Active accent bar — 4px mint, 펼쳐진 메뉴 + sub 전체 높이 */}
              {isExpanded && (
                <span className="pointer-events-none absolute bottom-0 left-0 top-0 w-1 bg-nav-accent" />
              )}

              {/* 1depth Menu Item — h-12 (48px) — Figma: expanded 시 text-white SemiBold + bg nav-active */}
              <button
                className={[
                  'flex h-12 w-full cursor-pointer items-center border-none bg-transparent',
                  'text-left tracking-[-0.16px] transition-colors duration-150',
                  collapsed ? 'justify-center px-0' : 'px-6',
                  isExpanded
                    ? 'text-lg-medium font-semibold bg-nav-active text-white'
                    : 'text-lg-medium text-nav-text-muted hover:bg-nav-active hover:text-white',
                ].join(' ')}
                onClick={() => onMenuClick?.(item.id)}
                aria-expanded={hasChildren ? isExpanded : undefined}
                aria-current={isActive ? 'page' : undefined}
              >
                {!collapsed && <span className="flex-1">{item.label}</span>}
                {hasChildren && !collapsed && (
                  // Figma: arrow_forward_ios 12, expanded 시 90° rotate (= 아래방향)
                  <Icon
                    name="arrow_forward_ios"
                    size={16}
                    decorative
                    className={[
                      'transition-transform duration-200',
                      isExpanded ? 'rotate-90 text-white' : 'text-nav-text-muted',
                    ].join(' ')}
                  />
                )}
              </button>

              {/* 2depth SubMenu — Figma: 행 자체 bg nav-active(#25323f), active 시 inner box bg nav-sub(#1f2a34) */}
              {hasChildren && isExpanded && !collapsed && (
                <div role="group" aria-label={`${item.label} 하위 메뉴`}>
                  {item.children!.map((sub) => {
                    const isSubActive = sub.id === activeSubMenuId;
                    return (
                      <div
                        key={sub.id}
                        className={[
                          'flex h-12 items-center bg-nav-active',
                          isSubActive ? 'px-3.5' : 'pl-10 pr-6',
                        ].join(' ')}
                      >
                        <button
                          className={[
                            'flex w-full cursor-pointer items-center border-none text-left',
                            'text-base-medium text-nav-text-muted tracking-[-0.14px] transition-colors duration-150',
                            isSubActive
                              ? 'h-[42px] bg-nav-sub px-[25px] py-[14px]'
                              : 'h-full bg-transparent hover:text-white',
                          ].join(' ')}
                          onClick={() => onSubMenuClick?.(item.id, sub.id)}
                          aria-current={isSubActive ? 'page' : undefined}
                        >
                          <span className="flex-1">{sub.label}</span>
                        </button>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}

        {/* Logout — Figma: h-48 px-24, no top border */}
        {showLogout && (
          <button
            className={[
              'mt-auto flex h-12 w-full cursor-pointer items-center border-none',
              'bg-transparent text-left text-lg-medium text-nav-text-muted tracking-[-0.16px]',
              'transition-colors duration-150 hover:bg-nav-active hover:text-white',
              collapsed ? 'justify-center px-0' : 'px-6',
            ].join(' ')}
            onClick={onLogoutClick}
          >
            {!collapsed && <span className="flex-1">로그아웃</span>}
            {collapsed && (
              <Icon name="logout" size={16} decorative />
            )}
          </button>
        )}
      </div>
    </nav>
  );
};
