import { forwardRef, type CSSProperties, type ElementType } from 'react';
import { cn } from '../../internal/cn';
import type { BoxProps } from './Box.types';
import type { SpacingToken } from './layout.types';

const P: Record<SpacingToken, string> = {
  0: 'p-0', 4: 'p-1', 8: 'p-2', 12: 'p-3', 16: 'p-4',
  24: 'p-6', 32: 'p-8', 48: 'p-12', 64: 'p-16',
};
const PX: Record<SpacingToken, string> = {
  0: 'px-0', 4: 'px-1', 8: 'px-2', 12: 'px-3', 16: 'px-4',
  24: 'px-6', 32: 'px-8', 48: 'px-12', 64: 'px-16',
};
const PY: Record<SpacingToken, string> = {
  0: 'py-0', 4: 'py-1', 8: 'py-2', 12: 'py-3', 16: 'py-4',
  24: 'py-6', 32: 'py-8', 48: 'py-12', 64: 'py-16',
};
const PT: Record<SpacingToken, string> = {
  0: 'pt-0', 4: 'pt-1', 8: 'pt-2', 12: 'pt-3', 16: 'pt-4',
  24: 'pt-6', 32: 'pt-8', 48: 'pt-12', 64: 'pt-16',
};
const PB: Record<SpacingToken, string> = {
  0: 'pb-0', 4: 'pb-1', 8: 'pb-2', 12: 'pb-3', 16: 'pb-4',
  24: 'pb-6', 32: 'pb-8', 48: 'pb-12', 64: 'pb-16',
};
const PL: Record<SpacingToken, string> = {
  0: 'pl-0', 4: 'pl-1', 8: 'pl-2', 12: 'pl-3', 16: 'pl-4',
  24: 'pl-6', 32: 'pl-8', 48: 'pl-12', 64: 'pl-16',
};
const PR: Record<SpacingToken, string> = {
  0: 'pr-0', 4: 'pr-1', 8: 'pr-2', 12: 'pr-3', 16: 'pr-4',
  24: 'pr-6', 32: 'pr-8', 48: 'pr-12', 64: 'pr-16',
};
const M: Record<SpacingToken, string> = {
  0: 'm-0', 4: 'm-1', 8: 'm-2', 12: 'm-3', 16: 'm-4',
  24: 'm-6', 32: 'm-8', 48: 'm-12', 64: 'm-16',
};
const MX: Record<SpacingToken, string> = {
  0: 'mx-0', 4: 'mx-1', 8: 'mx-2', 12: 'mx-3', 16: 'mx-4',
  24: 'mx-6', 32: 'mx-8', 48: 'mx-12', 64: 'mx-16',
};
const MY: Record<SpacingToken, string> = {
  0: 'my-0', 4: 'my-1', 8: 'my-2', 12: 'my-3', 16: 'my-4',
  24: 'my-6', 32: 'my-8', 48: 'my-12', 64: 'my-16',
};
const MT: Record<SpacingToken, string> = {
  0: 'mt-0', 4: 'mt-1', 8: 'mt-2', 12: 'mt-3', 16: 'mt-4',
  24: 'mt-6', 32: 'mt-8', 48: 'mt-12', 64: 'mt-16',
};
const MB: Record<SpacingToken, string> = {
  0: 'mb-0', 4: 'mb-1', 8: 'mb-2', 12: 'mb-3', 16: 'mb-4',
  24: 'mb-6', 32: 'mb-8', 48: 'mb-12', 64: 'mb-16',
};
const ML: Record<SpacingToken, string> = {
  0: 'ml-0', 4: 'ml-1', 8: 'ml-2', 12: 'ml-3', 16: 'ml-4',
  24: 'ml-6', 32: 'ml-8', 48: 'ml-12', 64: 'ml-16',
};
const MR: Record<SpacingToken, string> = {
  0: 'mr-0', 4: 'mr-1', 8: 'mr-2', 12: 'mr-3', 16: 'mr-4',
  24: 'mr-6', 32: 'mr-8', 48: 'mr-12', 64: 'mr-16',
};

export const Box = forwardRef<HTMLElement, BoxProps>(function Box(
  {
    as: Tag = 'div',
    padding,
    paddingX,
    paddingY,
    paddingTop,
    paddingBottom,
    paddingLeft,
    paddingRight,
    margin,
    marginX,
    marginY,
    marginTop,
    marginBottom,
    marginLeft,
    marginRight,
    width,
    height,
    minWidth,
    maxWidth,
    minHeight,
    maxHeight,
    full,
    fullHeight,
    grow,
    className,
    style,
    children,
    ...rest
  },
  ref
) {
  const classes = cn(
    padding !== undefined && P[padding],
    paddingX !== undefined && PX[paddingX],
    paddingY !== undefined && PY[paddingY],
    paddingTop !== undefined && PT[paddingTop],
    paddingBottom !== undefined && PB[paddingBottom],
    paddingLeft !== undefined && PL[paddingLeft],
    paddingRight !== undefined && PR[paddingRight],
    margin !== undefined && M[margin],
    marginX !== undefined && MX[marginX],
    marginY !== undefined && MY[marginY],
    marginTop !== undefined && MT[marginTop],
    marginBottom !== undefined && MB[marginBottom],
    marginLeft !== undefined && ML[marginLeft],
    marginRight !== undefined && MR[marginRight],
    full && 'w-full',
    fullHeight && 'h-full',
    grow && 'grow',
    className
  );

  const sizingStyle: CSSProperties = {
    ...(width !== undefined && { width }),
    ...(height !== undefined && { height }),
    ...(minWidth !== undefined && { minWidth }),
    ...(maxWidth !== undefined && { maxWidth }),
    ...(minHeight !== undefined && { minHeight }),
    ...(maxHeight !== undefined && { maxHeight }),
  };

  const Component = Tag as ElementType;
  return (
    <Component
      ref={ref}
      className={classes}
      style={{ ...sizingStyle, ...style }}
      {...rest}
    >
      {children}
    </Component>
  );
});
