import React, { useState } from 'react';
import type { Column, TableProps } from './Table.types';
import { Icon } from '../Icon';
import { Button } from '../Button';
import { cn } from '../../internal/cn';

/* ============================================
 * Table (Figma: DataTable)
 * Figma Source: 03_Components > DataTable
 * (props 는 staff Table 과 동일 — drop-in 대체용. + 툴바/빈상태 합성)
 *
 * 카드(rounded-8, border) 안에:
 *   [툴바] 총 N개 + 엑셀 다운로드 버튼 (totalCount/onExcelDownload 주면 표시)
 *          — Figma: 고정높이 없이 pt-8/pb-9, 버튼은 Button 30(sm)·아이콘 16
 *   [테이블] header bg gray-100 13 Regular gray-600 / row 55px 14 gray-950 / border gray-200
 *   [빈상태] empty(inbox) | noResult(search) — 48px 아이콘 + 안내문
 *
 * Checkbox·EmptyState 는 이 파일에 인라인.
 * ============================================ */

const DENSITY = {
  compact:     { row: 'h-10',     cell: 'py-3 px-4 text-base-regular', header: 'py-3 px-4 text-sm-regular' },
  normal:      { row: 'h-[40px]', cell: 'py-3 px-4 text-base-regular', header: 'py-3 px-4 text-sm-regular' },
  comfortable: { row: 'h-16',     cell: 'py-4 px-4 text-base-regular', header: 'py-4 px-4 text-sm-regular' },
} as const;

const SKELETON_ROWS = 5;

/* ── 인라인 Checkbox (sm) ── */
const CheckCell: React.FC<{
  checked: boolean;
  indeterminate?: boolean;
  onChange: () => void;
  ariaLabel: string;
}> = ({ checked, indeterminate = false, onChange, ariaLabel }) => (
  <button
    type="button"
    role="checkbox"
    aria-checked={indeterminate ? 'mixed' : checked}
    aria-label={ariaLabel}
    onClick={(e) => { e.stopPropagation(); onChange(); }}
    className={cn(
      'w-4 h-4 rounded-[4px] border-[1.5px] flex items-center justify-center transition-colors cursor-pointer',
      checked || indeterminate ? 'bg-primary border-primary' : 'border-border-hover bg-surface'
    )}
  >
    {indeterminate ? (
      <span className="w-2 h-0.5 rounded-full bg-white" />
    ) : checked ? (
      <svg width="10" height="8" viewBox="0 0 10 8" fill="none" aria-hidden="true">
        <path d="M1 4L3.5 6.5L9 1" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ) : null}
  </button>
);

/* ── 인라인 EmptyState (empty | noResult) ── */
const EmptyBlock: React.FC<{ variant: 'empty' | 'noResult' }> = ({ variant }) => {
  const isEmpty = variant === 'empty';
  return (
    <div className="flex flex-col items-center justify-center gap-4 py-20">
      <span className="text-gray-300">
        <Icon name={isEmpty ? 'inbox' : 'search'} size={48} decorative />
      </span>
      <div className="flex flex-col items-center text-center leading-[1.5]">
        <p className="text-lg-semibold text-gray-950">
          {isEmpty ? '데이터가 없습니다' : '검색 결과가 없습니다'}
        </p>
        <p className="text-base-regular text-gray-600">
          {isEmpty ? '새 항목을 추가해 주세요' : '다른 검색어로 시도하거나 필터를 초기화 하세요'}
        </p>
      </div>
    </div>
  );
};

export function Table<T extends Record<string, any>>({
  columns,
  data,
  rowIdKey = 'id',
  density = 'normal',
  selectable = false,
  selectedIds = [],
  onSelectionChange,
  sortBy,
  sortDirection,
  onSortChange,
  loading = false,
  emptyState,
  emptyVariant = 'empty',
  onRowClick,
  totalCount,
  onExcelDownload,
  excelLabel = '엑셀 다운로드',
  className,
  'data-testid': dataTestId,
  rowTestId,
}: TableProps<T>) {
  const [internalSortCol, setInternalSortCol] = useState<string | null>(null);
  const [internalSortDir, setInternalSortDir] = useState<'asc' | 'desc'>('asc');

  const activeSortCol = sortBy ?? internalSortCol;
  const activeSortDir = sortDirection ?? internalSortDir;

  const getRowId = (row: T, index: number): string =>
    typeof rowIdKey === 'function' ? rowIdKey(row) : String(row[rowIdKey] ?? index);

  const isAllSelected =
    data.length > 0 && data.every((row, i) => selectedIds.includes(getRowId(row, i)));
  const isIndeterminate =
    !isAllSelected && data.some((row, i) => selectedIds.includes(getRowId(row, i)));

  const toggleAll = () => {
    if (isAllSelected) onSelectionChange?.([]);
    else onSelectionChange?.(data.map((row, i) => getRowId(row, i)));
  };

  const toggleRow = (id: string) => {
    onSelectionChange?.(
      selectedIds.includes(id) ? selectedIds.filter((k) => k !== id) : [...selectedIds, id]
    );
  };

  const handleSort = (colId: string) => {
    const newDir = activeSortCol === colId && activeSortDir === 'asc' ? 'desc' : 'asc';
    if (onSortChange) onSortChange(colId, newDir);
    else { setInternalSortCol(colId); setInternalSortDir(newDir); }
  };

  const d = DENSITY[density];
  const lastColIdx = columns.length - 1;

  const getCellValue = (row: T, col: Column<T>, index: number) => {
    if (col.cell) return col.cell(row, index);
    if (col.accessorKey) return row[col.accessorKey];
    return row[col.id];
  };

  const showToolbar = totalCount != null || !!onExcelDownload;

  // 셀 경계: 행 구분(border-b) + 열 구분(마지막 컬럼 제외 border-r). 외곽은 카드가 담당.
  const cellBorder = (colIdx: number, isLast: boolean) =>
    cn('border-b border-border', !isLast && 'border-r border-border', selectable && colIdx === -1 && 'border-r border-border');

  return (
    <div
      className={cn('border border-border bg-surface overflow-hidden', showToolbar && 'rounded-[8px]', className)}
      data-testid={dataTestId}
    >
      {/* 툴바 */}
      {showToolbar && (
        <div className="flex items-center justify-between border-b border-border bg-gray-50 px-6 pt-2 pb-[9px]">
          <p className="text-base-regular text-gray-600">
            {totalCount != null && (
              <>총 <span className="text-base-semibold text-gray-950">{totalCount}</span>개</>
            )}
          </p>
          {onExcelDownload && (
            <Button
              variant="secondary"
              size="sm"
              onClick={onExcelDownload}
              leadingIcon={<Icon name="download" size={16} decorative />}
            >
              {excelLabel}
            </Button>
          )}
        </div>
      )}

      {/* 빈 상태(Figma): 컬럼 헤더 없이 툴바 + 빈 블록만 */}
      {data.length === 0 && !loading ? (
        emptyState ?? <EmptyBlock variant={emptyVariant} />
      ) : (
      <div className="w-full overflow-x-auto">
        <table className="w-full border-collapse" style={{ minWidth: 1200 }}>
          <thead>
            <tr className="bg-gray-100">
              {selectable && (
                <th className={cn('w-11 text-center', d.header, cellBorder(-1, false))}>
                  <div className="flex items-center justify-center">
                    <CheckCell
                      checked={isAllSelected}
                      indeterminate={isIndeterminate}
                      onChange={toggleAll}
                      ariaLabel="전체 선택"
                    />
                  </div>
                </th>
              )}
              {columns.map((col, ci) => (
                <th
                  key={col.id}
                  className={cn(
                    'whitespace-nowrap',
                    // Figma: 정렬 가능 헤더는 gray-500, 일반 헤더는 gray-600.
                    col.sortable ? 'text-gray-500' : 'text-gray-600',
                    d.header,
                    cellBorder(ci, ci === lastColIdx),
                    col.sortable && 'cursor-pointer select-none hover:text-gray-950'
                  )}
                  style={{ width: col.width, textAlign: col.align ?? 'center' }}
                  onClick={() => col.sortable && handleSort(col.id)}
                >
                  <span className="inline-flex items-center gap-1">
                    {col.header}
                    {col.sortable && (
                      <Icon
                        name={
                          activeSortCol === col.id
                            ? activeSortDir === 'asc' ? 'expand_less' : 'expand_more'
                            : 'expand_all'
                        }
                        size={16}
                        decorative
                      />
                    )}
                  </span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              Array.from({ length: SKELETON_ROWS }).map((_, i) => (
                <tr key={`skeleton-${i}`} className={d.row}>
                  {selectable && (
                    <td className={cn('w-11', d.cell, cellBorder(-1, false))}>
                      <div className="w-4 h-4 bg-gray-200 rounded animate-pulse mx-auto" />
                    </td>
                  )}
                  {columns.map((col, ci) => (
                    <td key={col.id} className={cn(d.cell, cellBorder(ci, ci === lastColIdx))}>
                      <div className="h-4 bg-gray-200 rounded animate-pulse" style={{ width: '60%' }} />
                    </td>
                  ))}
                </tr>
              ))
            ) : (
              data.map((row, rowIndex) => {
                const id = getRowId(row, rowIndex);
                const isSelected = selectedIds.includes(id);
                return (
                  <tr
                    key={id}
                    className={cn(
                      d.row,
                      'transition-colors',
                      onRowClick && 'cursor-pointer',
                      isSelected ? 'bg-[rgba(38,57,73,0.04)]' : 'bg-surface hover:bg-gray-50'
                    )}
                    onClick={() => onRowClick?.(row, rowIndex)}
                    data-testid={rowTestId ? rowTestId(row, id) : undefined}
                  >
                    {selectable && (
                      <td className={cn('w-11 text-center', d.cell, cellBorder(-1, false))}>
                        <div className="flex items-center justify-center">
                          <CheckCell
                            checked={isSelected}
                            onChange={() => toggleRow(id)}
                            ariaLabel={`행 ${rowIndex + 1} 선택`}
                          />
                        </div>
                      </td>
                    )}
                    {columns.map((col, ci) => (
                      <td
                        key={col.id}
                        className={cn(
                          'text-gray-950 max-w-[180px] truncate',
                          d.cell,
                          cellBorder(ci, ci === lastColIdx)
                        )}
                        style={{ textAlign: col.align ?? 'center' }}
                      >
                        {getCellValue(row, col, rowIndex)}
                      </td>
                    ))}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
      )}
    </div>
  );
}

Table.displayName = 'Table';
export const DataTable = Table;
