import React from 'react';
import type { ReactNode } from 'react';
import { cn } from '../../internal/cn';

/* ============================================
 * SingleSelection (Radio 패턴)
 * Figma Source: 03_Components > Single Selection (Radio 패턴)
 *
 * 선택 가능한 radio 행 목록(단일 선택). 기존 ad-hoc 선택 행 패턴을 대체.
 * 행 = radio + 라벨 + 우측 메타(description), 행 컨테이너에 선택 스타일.
 *
 * Figma 토큰:
 *   default:  border gray-200 / 라벨 Regular gray-950 / 메타 gray-600 / radio 빈 원(gray-200)
 *   selected: bg info-subtle + border info(#2563eb) / 라벨 SemiBold / radio primary
 *   disabled: border gray-200 / 라벨·메타 gray-400 / radio gray-200
 *   행: px-16 py-12 rounded-8, radio-라벨 gap 8, 메타 우측 정렬
 * ============================================ */

export interface SingleSelectionOption {
  value: string;
  label: string;
  /** 우측 메타 텍스트 (예: "담당: 서울 전체") */
  description?: ReactNode;
  disabled?: boolean;
}

export interface SingleSelectionProps {
  /** 라디오 그룹 name */
  name?: string;
  options: SingleSelectionOption[];
  value?: string;
  onChange?: (value: string) => void;
  className?: string;
  'data-testid'?: string;
}

export const SingleSelection: React.FC<SingleSelectionProps> = ({
  name,
  options,
  value,
  onChange,
  className,
  'data-testid': dataTestId,
}) => {
  return (
    <div role="radiogroup" className={cn('flex flex-col gap-2', className)} data-testid={dataTestId}>
      {options.map((opt) => {
        const selected = value === opt.value;
        const disabled = !!opt.disabled;
        return (
          <label
            key={opt.value}
            className={cn(
              'flex items-center justify-between gap-2 px-4 py-3 rounded-[8px] border transition-colors',
              disabled
                ? 'border-border cursor-not-allowed'
                : selected
                  ? 'border-info bg-info-subtle cursor-pointer'
                  : 'border-border hover:bg-surface-muted cursor-pointer'
            )}
          >
            <span className="flex items-center gap-2">
              <input
                type="radio"
                name={name}
                value={opt.value}
                checked={selected}
                disabled={disabled}
                onChange={() => !disabled && onChange?.(opt.value)}
                className="peer sr-only"
              />
              {/* radio 원 (Radio 컴포넌트와 동일 비주얼) */}
              <span
                aria-hidden="true"
                className={cn(
                  'relative inline-flex items-center justify-center w-[18px] h-[18px] rounded-full border bg-surface flex-shrink-0',
                  selected ? 'border-primary' : 'border-gray-200',
                  'peer-focus-visible:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]'
                )}
              >
                {selected && (
                  <span className={cn('w-2 h-2 rounded-full', disabled ? 'bg-gray-300' : 'bg-primary')} />
                )}
              </span>
              <span
                className={cn(
                  selected ? 'text-base-semibold' : 'text-base-regular',
                  disabled ? 'text-gray-400' : 'text-gray-950'
                )}
              >
                {opt.label}
              </span>
            </span>
            {opt.description != null && (
              <span className={cn('text-base-regular', disabled ? 'text-gray-400' : 'text-gray-600')}>
                {opt.description}
              </span>
            )}
          </label>
        );
      })}
    </div>
  );
};

SingleSelection.displayName = 'SingleSelection';
