import React, { useState } from 'react';
import { AdminLNB } from '../AdminLNB';
import type { AdminLNBProps } from '../AdminLNB';
import { AdminGNB } from '../AdminGNB';
import type { AdminGNBProps } from '../AdminGNB';
import { cn } from '../../internal/cn';

/* ============================================
 * AdminLayout — App Shell
 * AdminLNB(fixed) + AdminGNB(fixed) + 본문 offset 을 한 번에 처리하는 셸.
 *
 * AdminLNB/AdminGNB 는 position:fixed 라 소비 측에서 직접 배치하면 본문이 밑으로 깔린다.
 * 이 컴포넌트가 본문을 LNB 폭(ml-lnb)·GNB 높이(pt-gnb)만큼 offset 하고 collapse 를 관리한다.
 * (offset 유틸이 DS 내부에서 컴파일되므로 소비 레포의 @theme 설정과 무관하게 동작)
 * ============================================ */

export interface AdminLayoutProps {
  /** LNB 설정 (collapsed 는 내부 관리) */
  lnb: Omit<AdminLNBProps, 'collapsed'>;
  /** GNB 설정 (collapsed·onCollapseClick 은 내부 관리) */
  gnb?: Omit<AdminGNBProps, 'collapsed' | 'onCollapseClick'>;
  /** 본문 */
  children: React.ReactNode;
  className?: string;
  'data-testid'?: string;
}

export const AdminLayout: React.FC<AdminLayoutProps> = ({
  lnb,
  gnb,
  children,
  className,
  'data-testid': dataTestId,
}) => {
  const [collapsed, setCollapsed] = useState(false);

  return (
    <div className={cn('min-h-screen bg-gray-50', className)} data-testid={dataTestId}>
      <AdminLNB {...lnb} collapsed={collapsed} />
      <AdminGNB {...gnb} collapsed={collapsed} onCollapseClick={() => setCollapsed((v) => !v)} />
      <main
        className={cn(
          'min-h-screen pt-gnb transition-[margin-left] duration-200 ease-in-out',
          collapsed ? 'ml-0' : 'ml-lnb'
        )}
        role="main"
      >
        {children}
      </main>
    </div>
  );
};

AdminLayout.displayName = 'AdminLayout';
