import React, { forwardRef, useState, useRef, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { Icon } from '../Icon';
import type { DateFieldProps } from './DateField.types';

/* ============================================
 * DateField
 * Figma Source: 03_Components > DateField
 * (props 는 staff DateField 와 동일 — drop-in 대체용)
 *
 * Custom calendar popover (네이티브 date input 미사용), 280px popover
 * Size: 36px · rounded-8 · YYYY-MM-DD · 한글 날짜
 * States: Default · Hover · Focus · Filled · Error · Disabled (+ success/readOnly props 유지)
 *
 * Figma 토큰:
 *   label 13px Medium gray-600(disabled gray-400)
 *   border default → hover primary(#263949) · focus(open): 중립 border + ring 3px rgba(38,57,73,0.08)
 *   disabled bg gray-50 · placeholder gray-400 · calendar icon 18(Icon 20)
 *   (Figma Filled 값이 50% 반투명이나 가독성 위해 불투명 유지)
 * ============================================ */

const BORDER_STATUS: Record<NonNullable<DateFieldProps['status']>, string> = {
  default: 'border-border hover:border-primary',
  error: 'border-error',
  success: 'border-success',
};

const FOCUS_SHADOW: Record<NonNullable<DateFieldProps['status']>, string> = {
  default: '0 0 0 3px rgba(38,57,73,0.08)',
  error: '0 0 0 3px rgba(220,38,38,0.08)',
  success: '0 0 0 3px rgba(22,163,74,0.08)',
};

const WEEKDAYS = ['일', '월', '화', '수', '목', '금', '토'];
const MONTH_NAMES = ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'];

function parseDate(str: string): Date | null {
  if (!str) return null;
  const [y, m, d] = str.split('-').map(Number);
  if (!y || !m || !d) return null;
  return new Date(y, m - 1, d);
}

function formatDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function isSameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

export const DateField = forwardRef<HTMLInputElement, DateFieldProps>(
  (
    {
      label,
      name,
      value = '',
      onChange,
      placeholder = 'YYYY-MM-DD',
      status = 'default',
      errorMessage,
      successMessage,
      helperText,
      required = false,
      readOnly = false,
      disabled = false,
      minDate,
      maxDate,
      fullWidth = false,
      className,
      'data-testid': dataTestId,
    },
    ref
  ) => {
    const [open, setOpen] = useState(false);
    const [focused, setFocused] = useState(false);
    const selected = parseDate(value);
    const today = new Date();

    const [viewYear, setViewYear] = useState(selected?.getFullYear() ?? today.getFullYear());
    const [viewMonth, setViewMonth] = useState(selected?.getMonth() ?? today.getMonth());

    const containerRef = useRef<HTMLDivElement>(null);
    const fieldRef = useRef<HTMLDivElement>(null);
    const popoverRef = useRef<HTMLDivElement>(null);
    const [popoverStyle, setPopoverStyle] = useState<React.CSSProperties>({});

    const feedbackMessage =
      status === 'error' ? errorMessage : status === 'success' ? successMessage : helperText;

    // Popover 위치 계산: 입력 필드 좌하단 정렬, 우측 오버플로 시 우측 정렬로 flip
    const updatePopoverPosition = useCallback(() => {
      if (!fieldRef.current) return;
      const rect = fieldRef.current.getBoundingClientRect();
      const POPOVER_WIDTH = 280;
      const left =
        rect.left + POPOVER_WIDTH > window.innerWidth - 8
          ? Math.max(8, rect.right - POPOVER_WIDTH)
          : rect.left;
      setPopoverStyle({ position: 'fixed', top: rect.bottom + 4, left, zIndex: 600 });
    }, []);

    useEffect(() => {
      if (!open) return;
      updatePopoverPosition();
      window.addEventListener('scroll', updatePopoverPosition, true);
      window.addEventListener('resize', updatePopoverPosition);
      return () => {
        window.removeEventListener('scroll', updatePopoverPosition, true);
        window.removeEventListener('resize', updatePopoverPosition);
      };
    }, [open, updatePopoverPosition]);

    useEffect(() => {
      if (!open) return;
      const handler = (e: MouseEvent) => {
        const target = e.target as Node;
        if (containerRef.current?.contains(target)) return;
        if (popoverRef.current?.contains(target)) return;
        setOpen(false);
      };
      document.addEventListener('mousedown', handler);
      return () => document.removeEventListener('mousedown', handler);
    }, [open]);

    useEffect(() => {
      const d = parseDate(value);
      if (d) {
        setViewYear(d.getFullYear());
        setViewMonth(d.getMonth());
      }
    }, [value]);

    const navMonth = (dir: -1 | 1) => {
      let m = viewMonth + dir;
      let y = viewYear;
      if (m > 11) { m = 0; y++; }
      if (m < 0) { m = 11; y--; }
      setViewMonth(m);
      setViewYear(y);
    };

    const selectDate = useCallback((iso: string) => {
      onChange?.(iso);
      setOpen(false);
    }, [onChange]);

    const clearDate = () => {
      onChange?.('');
      setOpen(false);
    };

    const selectToday = () => {
      selectDate(formatDate(today));
    };

    const isDateDisabled = (date: Date): boolean => {
      if (minDate) {
        const min = parseDate(minDate);
        if (min && date < min) return true;
      }
      if (maxDate) {
        const max = parseDate(maxDate);
        if (max && date > max) return true;
      }
      return false;
    };

    const firstDay = new Date(viewYear, viewMonth, 1);
    const startDay = firstDay.getDay();
    const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
    const prevMonthDays = new Date(viewYear, viewMonth, 0).getDate();

    const cells: { day: number; iso: string; current: boolean; disabled: boolean }[] = [];

    for (let i = startDay - 1; i >= 0; i--) {
      const d = prevMonthDays - i;
      const date = new Date(viewYear, viewMonth - 1, d);
      cells.push({ day: d, iso: formatDate(date), current: false, disabled: true });
    }
    for (let d = 1; d <= daysInMonth; d++) {
      const date = new Date(viewYear, viewMonth, d);
      cells.push({ day: d, iso: formatDate(date), current: true, disabled: isDateDisabled(date) });
    }
    const remaining = (7 - cells.length % 7) % 7;
    for (let i = 1; i <= remaining; i++) {
      const date = new Date(viewYear, viewMonth + 1, i);
      cells.push({ day: i, iso: formatDate(date), current: false, disabled: true });
    }

    // Figma: focus(open) 시 border 중립 유지 + ring. hover 시 border primary.
    const fieldShadow = open || focused ? FOCUS_SHADOW[status] : 'none';
    const labelColorClass = disabled ? 'text-gray-400' : 'text-gray-600';

    return (
      <div
        ref={containerRef}
        className={[
          'relative flex flex-col gap-1.5 font-sans',
          fullWidth ? 'w-full' : 'inline-flex min-w-[148px]',
          className,
        ].filter(Boolean).join(' ')}
      >
        {label && (
          <label className={`text-sm-medium ${labelColorClass}`}>
            {label}
            {required && <span className="ml-0.5 text-error">*</span>}
          </label>
        )}

        {/* Input field */}
        <div
          ref={fieldRef}
          className={[
            'flex items-center h-9 rounded-[8px] border bg-surface cursor-pointer transition-all duration-200 overflow-hidden',
            BORDER_STATUS[status],
            disabled ? 'bg-gray-50 cursor-not-allowed opacity-60' : '',
          ].filter(Boolean).join(' ')}
          style={{ boxShadow: fieldShadow }}
          onClick={() => {
            if (!disabled && !readOnly) setOpen(!open);
          }}
        >
          <input
            ref={ref}
            type="text"
            name={name}
            value={value}
            placeholder={placeholder}
            data-testid={dataTestId}
            readOnly
            disabled={disabled}
            aria-invalid={status === 'error'}
            aria-required={required}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            className={[
              'flex-1 min-w-0 h-full pl-3 pr-1 bg-transparent outline-none text-gray-950 cursor-pointer text-base-regular',
              'placeholder:text-gray-400',
              'disabled:cursor-not-allowed disabled:text-gray-400',
            ].join(' ')}
            tabIndex={disabled ? -1 : 0}
          />
          {/* Calendar icon — Figma: calendar_today 18 (Icon 20). error 시 빨강 */}
          <span
            className={[
              'flex items-center justify-center pl-1 pr-2 flex-shrink-0 transition-colors',
              disabled
                ? 'text-gray-400'
                : status === 'error'
                  ? 'text-error'
                  : 'text-gray-600 hover:text-gray-950',
            ].filter(Boolean).join(' ')}
            aria-hidden="true"
          >
            <Icon name="calendar_today" size={20} decorative />
          </span>
        </div>

        {/* Calendar popover — portal 로 렌더링 */}
        {open && createPortal(
          <div
            ref={popoverRef}
            style={popoverStyle}
            className="w-[280px] bg-surface border border-border rounded-md p-4 shadow-[0_4px_24px_rgba(0,0,0,0.1)]"
          >
            <div className="flex items-center justify-between mb-3">
              <button
                type="button"
                className="w-7 h-7 flex items-center justify-center rounded-md text-gray-600 hover:bg-surface-muted transition-colors"
                onClick={() => navMonth(-1)}
              >
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                  <path d="M10 4L6 8L10 12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </button>
              <span className="text-sm-medium text-gray-950">
                {viewYear}년 {MONTH_NAMES[viewMonth]}
              </span>
              <button
                type="button"
                className="w-7 h-7 flex items-center justify-center rounded-md text-gray-600 hover:bg-surface-muted transition-colors"
                onClick={() => navMonth(1)}
              >
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                  <path d="M6 4L10 8L6 12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </button>
            </div>

            <div className="grid grid-cols-7 mb-0.5">
              {WEEKDAYS.map((wd) => (
                <span key={wd} className="text-xs-medium text-gray-400 text-center py-1">
                  {wd}
                </span>
              ))}
            </div>

            <div className="grid grid-cols-7 gap-px">
              {cells.map((cell, i) => {
                const isSelected = selected && cell.iso === value;
                const isToday = cell.current && isSameDay(new Date(viewYear, viewMonth, cell.day), today);

                return (
                  <button
                    key={i}
                    type="button"
                    disabled={cell.disabled}
                    onClick={() => !cell.disabled && selectDate(cell.iso)}
                    className={[
                      'w-9 h-9 flex items-center justify-center text-sm-regular rounded-md transition-colors',
                      cell.disabled
                        ? 'text-border-hover cursor-default'
                        : isSelected
                          ? 'text-sm-medium bg-primary text-white hover:bg-primary-hover'
                          : isToday
                            ? 'text-sm-medium text-gray-950 shadow-[inset_0_0_0_1px_var(--border-hover)] hover:bg-surface-muted'
                            : 'text-gray-950 hover:bg-surface-muted cursor-pointer',
                    ].join(' ')}
                  >
                    {cell.day}
                  </button>
                );
              })}
            </div>

            <div className="flex justify-between items-center mt-3 pt-3 border-t border-border">
              <button
                type="button"
                className="text-xs-medium text-gray-600 hover:bg-surface-muted hover:text-gray-950 px-2 py-1 rounded-md transition-colors"
                onClick={selectToday}
              >
                오늘
              </button>
              <button
                type="button"
                className="text-xs-medium text-gray-400 hover:text-error hover:bg-error-subtle px-2 py-1 rounded-md transition-colors"
                onClick={clearDate}
              >
                삭제
              </button>
            </div>
          </div>,
          document.body
        )}

        {/* Feedback message (12px icon + 4px gap) */}
        {feedbackMessage && (
          <div
            className={[
              'flex items-center gap-1 text-xs-regular font-sans',
              status === 'error' ? 'text-error' : status === 'success' ? 'text-success' : 'text-gray-400',
            ].join(' ')}
          >
            {status === 'error' && (
              <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
                <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
                <path d="M6 3.5v3M6 8.5v.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
              </svg>
            )}
            {status === 'success' && (
              <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
                <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
                <path d="M4 6l1.5 1.5L8 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            )}
            {status === 'default' && (
              <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
                <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
                <path d="M6 5.5v3M6 3.75v.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
              </svg>
            )}
            <span>{feedbackMessage}</span>
          </div>
        )}
      </div>
    );
  }
);

DateField.displayName = 'DateField';
