/**
 * 클래스명 머지 헬퍼.
 *
 * - tailwind-merge 사용: 동일 property 충돌 시 **뒤에 온 클래스가 이김**
 * - 호출 패턴은 `cn(BASE, conditional, className)` — 호출자가 넘긴 `className` 을 마지막에 두면 자동으로 사용자 className 이 우선
 * - falsy 값(`false | null | undefined | 0`) 은 자동 무시
 *
 * Staff DS 의 커스텀 text-style 유틸(`text-sm-medium`, `text-base-medium`, `text-page-title` 등)은
 * tailwind-merge 기본 인식 규칙상 `text-{color}-{shade}` 패턴과 구분이 안 돼 text-color 로 오인되는 문제가 있다.
 * `extendTailwindMerge` 로 명시적으로 font-size 그룹에 등록해 충돌 오판을 막는다.
 *
 * 토큰 목록은 `src/styles/index.css` 의 `@utility text-*` 정의(Figma 15 Text Styles)와 1:1 매칭된다.
 *
 * 비공개 — 외부 export 하지 않는다.
 */
import { extendTailwindMerge } from 'tailwind-merge';

const TEXT_STYLE_TOKENS = [
  'text-xs-regular',
  'text-xs-medium',
  'text-sm-regular',
  'text-sm-medium',
  'text-base-regular',
  'text-base-medium',
  'text-base-semibold',
  'text-lg-medium',
  'text-lg-semibold',
  'text-inner-tab',
  'text-inner-tab-active',
  'text-xl-semibold',
  'text-2xl-bold',
  'text-page-title',
  'text-lnb-logo',
];

export const cn = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': TEXT_STYLE_TOKENS,
    },
  },
});
