import { forwardRef } from 'react';
import type { BadgeProps, BadgeStatus, SemanticStatus } from './Badge.types';
import { cn } from '../../internal/cn';

/* ============================================
 * Badge
 * Figma Source: 03_Components > Badge (domain)
 * + staff StatusBadge 호환 확장(semantic/size/custom색)
 *
 * domain: pill h20 · px8 py4 · 6px dot + 한글 라벨 · 12px SemiBold · 토큰 색 (Figma 정본)
 * semantic: size(sm/md/lg) · inline 의미색 · 12~13px Medium · dot 기본 숨김 · children 라벨
 * ============================================ */

const DOMAIN: Record<BadgeStatus, { label: string; bg: string; text: string; dot: string }> = {
  pending:   { label: '대기',     bg: 'bg-badge-pending-bg',   text: 'text-badge-pending-text',   dot: 'bg-badge-pending-dot' },
  assigned:  { label: '배정완료', bg: 'bg-badge-assigned-bg',  text: 'text-badge-assigned-text',  dot: 'bg-badge-assigned-dot' },
  completed: { label: '완료',     bg: 'bg-badge-completed-bg', text: 'text-badge-completed-text', dot: 'bg-badge-completed-dot' },
  cancelled: { label: '취소',     bg: 'bg-badge-cancelled-bg', text: 'text-badge-cancelled-text', dot: 'bg-badge-cancelled-dot' },
  unable:    { label: '작업불가', bg: 'bg-badge-unable-bg',    text: 'text-badge-unable-text',    dot: 'bg-badge-unable-dot' },
};

const SEMANTIC: Record<SemanticStatus, { bg: string; text: string; dot: string }> = {
  success: { bg: 'rgba(22,163,74,0.06)', text: '#16A34A', dot: '#16A34A' },
  warning: { bg: '#FFF7ED', text: '#B45309', dot: '#F59E0B' },
  info:    { bg: '#EFF6FF', text: '#1D4ED8', dot: '#3B82F6' },
  error:   { bg: '#FEF2F2', text: '#DC2626', dot: '#DC2626' },
  neutral: { bg: '#F4F4F5', text: '#71717A', dot: '#A1A1AA' },
};

const DOMAIN_SET = new Set<string>(['pending', 'assigned', 'completed', 'cancelled', 'unable']);

const SIZE = {
  sm: 'px-1.5 py-0.5 text-xs-medium',
  md: 'px-2 py-1 text-xs-medium',
  lg: 'px-3 py-1.5 text-sm-medium',
} as const;

const DOT_SIZE = { sm: 'w-1 h-1', md: 'w-1.5 h-1.5', lg: 'w-2 h-2' } as const;

export const Badge = forwardRef<HTMLSpanElement, BadgeProps>(function Badge(
  { status, children, size = 'md', icon, showDot, backgroundColor, textColor, dotColor, className, ...rest },
  ref
) {
  const isDomain = DOMAIN_SET.has(status);
  const shouldShowDot = showDot ?? isDomain;

  // 색 해석: domain=토큰 클래스(커스텀 없을 때) / semantic=inline
  let colorClass = '';
  let dotClass = '';
  const style: React.CSSProperties = {};
  let dotStyle: React.CSSProperties = {};
  let label = children;

  if (isDomain) {
    const d = DOMAIN[status as BadgeStatus];
    label = children ?? d.label;
    if (backgroundColor) style.backgroundColor = backgroundColor;
    else colorClass = cn(colorClass, d.bg);
    if (textColor) style.color = textColor;
    else colorClass = cn(colorClass, d.text);
    if (dotColor) dotStyle = { backgroundColor: dotColor };
    else dotClass = d.dot;
  } else {
    const s = SEMANTIC[status as SemanticStatus];
    style.backgroundColor = backgroundColor ?? s.bg;
    style.color = textColor ?? s.text;
    dotStyle = { backgroundColor: dotColor ?? s.dot };
  }

  // 크기: domain 기본(md)은 Figma 고정(h20·12 SemiBold), 그 외 SIZE 맵
  const sizeCls =
    isDomain && size === 'md'
      ? 'h-5 px-2 py-1 text-[12px] font-semibold'
      : SIZE[size];

  return (
    <span
      ref={ref}
      className={cn(
        'inline-flex items-center gap-1.5 rounded-full font-sans whitespace-nowrap leading-none',
        sizeCls,
        colorClass,
        className
      )}
      style={Object.keys(style).length ? style : undefined}
      {...rest}
    >
      {shouldShowDot && !icon && (
        <span
          aria-hidden="true"
          className={cn('shrink-0 rounded-full', DOT_SIZE[size], dotClass)}
          style={Object.keys(dotStyle).length ? dotStyle : undefined}
        />
      )}
      {icon && (
        <span aria-hidden="true" className="flex items-center leading-none">
          {icon}
        </span>
      )}
      {label != null && <span>{label}</span>}
    </span>
  );
});

Badge.displayName = 'Badge';
