import React, { useState } from 'react';
import type { ReactNode } from 'react';
import { Icon } from '../Icon';
import { cn } from '../../internal/cn';

/* ============================================
 * ModalDropdown (Collapsible / 펼침·닫힘)
 * Figma Source: modal-dropdown (default 닫힘 / active 펼침)
 *
 * 헤더(chevron + 타이틀) 클릭으로 content 영역을 펼치고 접는다.
 * controlled(open) / uncontrolled(defaultOpen) 모두 지원.
 *
 * Figma 토큰:
 *   card: bg-surface, border gray-200, rounded-16
 *   닫힘: px-16 py-8 (헤더만) · 아이콘 keyboard_arrow_up
 *   펼침: p-16, 헤더↔content gap-8 · 아이콘 keyboard_arrow_down
 *   타이틀 14 Medium gray-950 · content 14 Regular gray-600
 * ============================================ */

export interface ModalDropdownProps {
  title: ReactNode;
  children: ReactNode;
  /** uncontrolled 초기 펼침 여부 */
  defaultOpen?: boolean;
  /** controlled 펼침 상태 */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
  'data-testid'?: string;
}

export const ModalDropdown: React.FC<ModalDropdownProps> = ({
  title,
  children,
  defaultOpen = false,
  open: openProp,
  onOpenChange,
  className,
  'data-testid': dataTestId,
}) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isControlled = openProp !== undefined;
  const open = isControlled ? openProp : internalOpen;

  const toggle = () => {
    const next = !open;
    if (!isControlled) setInternalOpen(next);
    onOpenChange?.(next);
  };

  return (
    <div
      className={cn(
        'w-full rounded-[16px] border border-border bg-surface',
        open ? 'p-4' : 'px-4 py-2',
        className
      )}
      data-testid={dataTestId}
    >
      <button
        type="button"
        onClick={toggle}
        aria-expanded={open}
        className="flex w-full items-center gap-2 text-left cursor-pointer"
      >
        <span className="flex text-gray-950">
          <Icon name={open ? 'keyboard_arrow_down' : 'keyboard_arrow_up'} size={24} decorative />
        </span>
        <span className="text-base-medium text-gray-950">{title}</span>
      </button>
      {open && <div className="mt-2 text-base-regular text-gray-600">{children}</div>}
    </div>
  );
};

ModalDropdown.displayName = 'ModalDropdown';
