import React from 'react';
import type { HTMLAttributes, ReactNode } from 'react';
import { cn } from '../../internal/cn';

/* ============================================
 * Label (제거 가능한 태그/칩)
 * Figma Source: label
 *
 * pill 형태 태그 — bg gray-100, border gray-200, 12 Medium, (X 제거 버튼).
 * onRemove 지정 시 우측 X(close) 표시.
 *
 * Figma 토큰:
 *   pill rounded-full, bg gray-100, border gray-200, px-12 py-8, gap-4
 *   텍스트 12 Medium gray-950 · close 16
 * ============================================ */

export interface LabelProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  children: ReactNode;
  /** 지정 시 우측 X 표시 + 클릭 시 호출 */
  onRemove?: () => void;
  /** X 버튼 aria-label (기본 "제거") */
  removeAriaLabel?: string;
}

export const Label: React.FC<LabelProps> = ({
  children,
  onRemove,
  removeAriaLabel = '제거',
  className,
  ...rest
}) => {
  return (
    <span
      className={cn(
        'inline-flex items-center justify-center gap-1 rounded-full border border-border bg-gray-100 px-3 py-2 font-sans',
        className
      )}
      {...rest}
    >
      <span className="text-xs-medium text-gray-950">{children}</span>
      {onRemove && (
        <button
          type="button"
          onClick={onRemove}
          aria-label={removeAriaLabel}
          className="flex text-gray-500 hover:text-gray-950 transition-colors cursor-pointer"
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
            <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </span>
  );
};

Label.displayName = 'Label';
