import React, { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Button } from '../Button';
import { InlineAlert } from '../InlineAlert';
import type { ModalProps } from './Modal.types';

import { cn } from '../../internal/cn';
import { IDS_Z_INDEX } from '../../internal/zIndex';

/* ============================================
 * Modal — 선언형 <Modal>
 * Figma Source: Component/Modal (node 392:953)
 *
 * 중앙 대화상자. 확인/간단한 폼/알림용.
 * Size: sm(400) | md(560) | lg(720) | xl(960)
 * Variant: default | danger (primary 버튼 스타일)
 *
 * Footer:
 *   - footer prop → 커스텀 footer
 *   - primaryLabel/onPrimary → 자동 생성 footer (Secondary 취소 + Primary 저장/확인)
 *   - 둘 다 없으면 footer 없음
 *
 * Backdrop: rgba(0,0,0,0.4)
 * createPortal(document.body) 로 렌더 — imperative ModalRoot 와 동일한 스택 동작.
 * ============================================ */

const SIZE_CLASS: Record<NonNullable<ModalProps['size']>, string> = {
  sm: 'w-full max-w-[400px]',
  md: 'w-full max-w-[560px]',
  lg: 'w-full max-w-[720px]',
  xl: 'w-full max-w-[960px]',
};

export const Modal: React.FC<ModalProps> = ({
  open,
  onClose,
  title,
  headerExtra,
  description,
  size = 'md',
  variant = 'default',
  loading = false,
  error,
  primaryLabel,
  onPrimary,
  secondaryLabel,
  onSecondary,
  preventClose = false,
  closeOnBackdrop = false,
  disablePadding = false,
  footer,
  children,
  className,
  'data-testid': dataTestId,
  'data-testid-close': dataTestIdClose,
}) => {
  const dialogRef = useRef<HTMLDivElement>(null);
  // SSR 가드 — 마운트 후에만 portal 렌더.
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  // ESC key
  useEffect(() => {
    if (!open || preventClose) return;
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', handleEsc);
    return () => document.removeEventListener('keydown', handleEsc);
  }, [open, onClose, preventClose]);

  // Lock body scroll (중첩 모달 안전: 원래값 저장 후 복원)
  useEffect(() => {
    if (!open) return;
    const original = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = original;
    };
  }, [open]);

  if (!open || !mounted) return null;

  const handleBackdropClick = () => {
    // 기본은 backdrop 클릭으로 닫지 않음 — closeOnBackdrop=true 일 때만 닫는다 (X 버튼은 항상 동작).
    if (!preventClose && closeOnBackdrop) onClose();
  };

  // Auto-generate footer from primaryLabel/secondaryLabel
  const hasAutoFooter = primaryLabel || onPrimary;
  const renderFooter = () => {
    if (footer) return footer;
    if (!hasAutoFooter) return null;
    return (
      <div className="flex items-center justify-end gap-2">
        {(secondaryLabel || onSecondary) && (
          <Button
            variant="secondary"
            onClick={onSecondary ?? onClose}
            disabled={loading}
          >
            {secondaryLabel ?? '취소'}
          </Button>
        )}
        {(primaryLabel || onPrimary) && (
          <Button
            variant={variant === 'danger' ? 'danger' : 'primary'}
            onClick={onPrimary}
            loading={loading}
          >
            {primaryLabel ?? '확인'}
          </Button>
        )}
      </div>
    );
  };

  const footerContent = renderFooter();

  return createPortal(
    <div
      className="fixed inset-0 flex items-center justify-center bg-black/40"
      style={{ zIndex: IDS_Z_INDEX.MODAL }}
      onClick={handleBackdropClick}
    >
      <div
        ref={dialogRef}
        className={cn(
          'flex flex-col bg-surface rounded-[8px] border border-gray-50 shadow-[-4px_0px_24px_0px_rgba(0,0,0,0.1)] max-h-[90vh]',
          SIZE_CLASS[size],
          className
        )}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        data-testid={dataTestId}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header — Figma: px-24 / pt-20 / pb-21 / border-bottom */}
        <div className="flex items-start justify-between px-6 pt-5 pb-[21px] border-b border-gray-50 flex-shrink-0">
          <div className="flex items-center gap-3 flex-1 min-w-0">
            <h2 id="modal-title" className="text-xl-semibold text-gray-950 leading-tight">
              {title}
            </h2>
            {headerExtra}
            {description && (
              <p className="mt-1 text-sm-regular text-gray-500">{description}</p>
            )}
          </div>
          <button
            type="button"
            onClick={onClose}
            disabled={preventClose}
            aria-label="닫기"
            data-testid={dataTestIdClose}
            className={cn(
              'flex items-center justify-center w-10 h-10 rounded-md text-gray-400 transition-colors duration-150 flex-shrink-0 ml-4',
              preventClose
                ? 'opacity-30 cursor-not-allowed'
                : 'hover:bg-surface-muted hover:text-gray-950'
            )}
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        {/* Error Banner — InlineAlert(error) 재사용 */}
        {error && (
          <div className="px-6 pt-3">
            <InlineAlert status="error">{error}</InlineAlert>
          </div>
        )}

        {/* Body — Figma: content padding 24px. disablePadding=true 시 제거 */}
        <div
          className={cn(
            'flex-1 overflow-y-auto',
            !disablePadding && 'p-6'
          )}
        >
          {children}
        </div>

        {/* Footer — Figma: px-24 / pt-17 / pb-16 / border-top */}
        {footerContent && (
          <div className="px-6 pt-[17px] pb-4 border-t border-gray-50 flex-shrink-0">
            {footerContent}
          </div>
        )}
      </div>
    </div>,
    document.body
  );
};

Modal.displayName = 'Modal';
export default Modal;
