import React, { useState, useRef, useEffect } from 'react';
import type { SelectProps } from './Select.types';
import { cn } from '../../internal/cn';

/* ============================================
 * Select
 * Figma Source: 03_Components > Select
 * (props 는 staff Select 와 동일 — drop-in 대체용)
 *
 * Size: 36px · rounded-8
 * States: Default · Hover · Focus · Filled · Error · Success · Disabled · ReadOnly
 *
 * Figma 토큰:
 *   label 13px Regular gray-600 (disabled/readonly gray-400)
 *   border default → hover primary(#263949) · focus(open): 중립 border + ring 3px rgba(38,57,73,0.08)
 *   disabled/readOnly bg gray-50 · placeholder gray-900 · 선택값 gray-950 (readOnly 값 gray-600)
 * 구현: 커스텀 div 기반 (네이티브 <select> 미사용)
 * ============================================ */

const BORDER_STATUS: Record<NonNullable<SelectProps['status']>, string> = {
  default: 'border-border hover:border-primary',
  error: 'border-error',
  success: 'border-success',
};

const FOCUS_SHADOW: Record<NonNullable<SelectProps['status']>, string> = {
  default: '0 0 0 3px rgba(38,57,73,0.08)',
  error: '0 0 0 3px rgba(220,38,38,0.08)',
  success: '0 0 0 3px rgba(22,163,74,0.08)',
};

/* ── Icons ── */
const ArrowDropDown: React.FC = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" className="flex-shrink-0">
    <path d="M7 10l5 5 5-5z" />
  </svg>
);

const ErrorIcon18: React.FC = () => (
  <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="9" cy="9" r="8" stroke="currentColor" strokeWidth="1.5" />
    <path d="M9 5.5v4M9 12v.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

const SuccessIcon18: React.FC = () => (
  <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="9" cy="9" r="8" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6 9l2 2 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/* ── Message icons (12px) ── */
const ErrorMsgIcon: React.FC = () => (
  <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6 3.5v3M6 8.5v.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

const SuccessMsgIcon: React.FC = () => (
  <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M4 6l1.5 1.5L8 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

const InfoMsgIcon: React.FC = () => (
  <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6 5.5v3M6 3.75v.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

/* ── Feedback Message ── */
const FeedbackMessage: React.FC<{
  status: NonNullable<SelectProps['status']>;
  errorMessage?: string;
  successMessage?: string;
  helperText?: string;
  id?: string;
}> = ({ status, errorMessage, successMessage, helperText, id }) => {
  const feedbackStatus =
    status === 'error' && errorMessage ? 'error'
    : status === 'success' && successMessage ? 'success'
    : helperText ? 'helper'
    : null;

  const message =
    feedbackStatus === 'error' ? errorMessage
    : feedbackStatus === 'success' ? successMessage
    : helperText;

  if (!message) return null;

  const colorClass =
    feedbackStatus === 'error' ? 'text-error'
    : feedbackStatus === 'success' ? 'text-success'
    : 'text-gray-400';

  return (
    <div id={id} className={`flex items-center gap-1 text-xs-regular font-sans ${colorClass}`}>
      {feedbackStatus === 'error' && <ErrorMsgIcon />}
      {feedbackStatus === 'success' && <SuccessMsgIcon />}
      {feedbackStatus === 'helper' && <InfoMsgIcon />}
      <span>{message}</span>
    </div>
  );
};

/* ── Select (커스텀 div 기반, 모든 모드 통합) ── */
export const Select: React.FC<SelectProps> = ({
  label, options, placeholder = '선택', value, onChange,
  searchable = false, onSearchChange, onScrollEnd, hasMore = false, loadingMore = false,
  multiple = false, status = 'default',
  errorMessage, successMessage, helperText, required, disabled,
  readOnly, fullWidth, id, className,
  'data-testid': dataTestId,
}) => {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const feedbackId = id ? `${id}-feedback` : undefined;

  const selectedValues: string[] = multiple
    ? (Array.isArray(value) ? value : [])
    : (value != null && value !== '' ? [value as string] : []);

  // 서버사이드 검색(onSearchChange)이면 client-side 재필터링하지 않는다.
  const filteredOptions = searchable && search && !onSearchChange
    ? options.filter((o) => o.label.toLowerCase().includes(search.toLowerCase()))
    : options;

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
        setSearch('');
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const toggleOption = (optValue: string) => {
    if (multiple) {
      const arr = Array.isArray(value) ? value : [];
      const next = arr.includes(optValue) ? arr.filter((v) => v !== optValue) : [...arr, optValue];
      onChange?.(next);
    } else {
      onChange?.(optValue);
      setOpen(false);
      setSearch('');
    }
  };

  const removeValue = (optValue: string) => {
    if (multiple && Array.isArray(value)) onChange?.(value.filter((v) => v !== optValue));
  };

  const getLabel = (v: string) => options.find((o) => o.value === v)?.label ?? v;
  const displayText = !multiple && selectedValues.length === 1 ? getLabel(selectedValues[0]) : '';
  const focusShadow = open ? FOCUS_SHADOW[status] : 'none';
  const isInteractionDisabled = disabled || readOnly;
  const labelColorClass = isInteractionDisabled ? 'text-gray-400' : 'text-gray-600';

  return (
    <div ref={containerRef} className={cn('relative font-sans flex flex-col gap-1.5', fullWidth ? 'w-full' : 'inline-flex min-w-[180px]', className)}>
      {label && (
        <label htmlFor={id} className={`text-sm-regular ${labelColorClass}`}>
          {label}{required && <span className="ml-0.5 text-error">*</span>}
        </label>
      )}

      {/* Trigger — Figma: flex justify-between, h-36, px-12, rounded-8, border 1px */}
      <div
        className={[
          'flex items-center h-9 rounded-[8px] border bg-surface transition-all duration-200 overflow-hidden',
          multiple ? 'flex-wrap gap-1 px-3 py-1' : 'px-3',
          BORDER_STATUS[status],
          disabled ? 'bg-gray-50 cursor-not-allowed opacity-60' : '',
          readOnly ? 'bg-gray-50 cursor-default pointer-events-none' : 'cursor-pointer',
        ].filter(Boolean).join(' ')}
        style={{ boxShadow: focusShadow }}
        data-testid={dataTestId}
        onClick={() => {
          if (isInteractionDisabled) return;
          setOpen(!open);
          if (!open && searchable) setTimeout(() => inputRef.current?.focus(), 0);
        }}
        role="combobox"
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-invalid={status === 'error'}
        aria-required={required}
        aria-describedby={feedbackId}
        tabIndex={isInteractionDisabled ? -1 : 0}
        onKeyDown={(e) => {
          if (isInteractionDisabled) return;
          if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setOpen(!open); }
          if (e.key === 'Escape') setOpen(false);
        }}
      >
        {/* Multi-select chips */}
        {multiple && selectedValues.map((v) => (
          <span key={v} className="inline-flex h-5 items-center gap-1 bg-gray-100 border border-gray-200 text-gray-950 text-[12px] font-medium leading-none px-2 rounded-full">
            <span className="leading-none translate-y-px">{getLabel(v)}</span>
            <button
              type="button"
              className="flex items-center justify-center text-gray-400 hover:text-gray-950 leading-none"
              onClick={(e) => { e.stopPropagation(); removeValue(v); }}
              aria-label={`${getLabel(v)} 제거`}
            >
              <svg width="10" height="10" viewBox="0 0 10 10" fill="none" aria-hidden="true">
                <path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
              </svg>
            </button>
          </span>
        ))}

        {/* Search input or display text */}
        {searchable && open ? (
          <input
            ref={inputRef}
            type="text"
            className="flex-1 min-w-[80px] bg-transparent outline-none text-base-regular text-gray-950 placeholder:text-gray-900"
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              onSearchChange?.(e.target.value);
            }}
            placeholder={selectedValues.length === 0 ? placeholder : '검색...'}
            onClick={(e) => e.stopPropagation()}
          />
        ) : (
          <span className={[
            'flex-1 truncate text-base-regular',
            selectedValues.length === 0
              ? 'text-gray-900' // Figma: placeholder gray-900
              : readOnly
                ? 'text-gray-600' // Figma: readOnly 값은 muted(gray-600)
                : 'text-gray-950',
          ].join(' ')}>
            {displayText || (selectedValues.length === 0 && !multiple ? placeholder : '')}
          </span>
        )}

        {/* Right icons — Figma: (status icon 18) + arrow_drop_down 18, gap-4 */}
        <div className="ml-auto flex items-center gap-1 flex-shrink-0">
          {status === 'error' && <span className="text-error"><ErrorIcon18 /></span>}
          {status === 'success' && <span className="text-success"><SuccessIcon18 /></span>}
          <span className={['text-gray-400 transition-transform duration-150', open && 'rotate-180'].filter(Boolean).join(' ')}>
            <ArrowDropDown />
          </span>
        </div>
      </div>

      {/* Dropdown panel */}
      {open && (
        <div
          className="absolute z-50 mt-1 w-full bg-surface border border-border rounded-md shadow-lg max-h-[200px] overflow-y-auto"
          style={{ top: '100%', overscrollBehavior: 'none', backgroundColor: 'var(--surface)' }}
          onScroll={(e) => {
            if (!onScrollEnd || !hasMore || loadingMore) return;
            const el = e.currentTarget;
            if (el.scrollTop + el.clientHeight >= el.scrollHeight - 24) {
              onScrollEnd();
            }
          }}
        >
          {filteredOptions.length === 0 && !loadingMore ? (
            <div className="px-3 py-2 text-sm-regular text-gray-400">검색 결과 없음</div>
          ) : (
            filteredOptions.map((opt) => {
              const isSelected = selectedValues.includes(opt.value);
              return (
                <div
                  key={opt.value}
                  role="option"
                  aria-selected={isSelected}
                  className={[
                    'flex items-center gap-2 px-3 py-2 transition-colors',
                    opt.disabled ? 'text-gray-400 cursor-not-allowed' : 'cursor-pointer',
                    isSelected ? 'text-base-medium bg-[rgba(38,57,73,0.06)] text-primary' : 'text-base-regular text-gray-950 hover:bg-surface-muted',
                  ].join(' ')}
                  onClick={() => !opt.disabled && toggleOption(opt.value)}
                >
                  {multiple && (
                    <span className={['w-4 h-4 rounded-[4px] border-[1.5px] flex items-center justify-center flex-shrink-0', isSelected ? 'bg-primary border-primary' : 'border-border-hover'].join(' ')}>
                      {isSelected && (
                        <svg width="10" height="8" viewBox="0 0 10 8" fill="none"><path d="M1 4L3.5 6.5L9 1" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
                      )}
                    </span>
                  )}
                  {opt.description ? (
                    <div className="flex flex-col gap-0.5">
                      <span className="text-base-medium text-gray-950">{opt.label}</span>
                      <span className="text-xs-regular text-gray-400 whitespace-pre-line">{opt.description}</span>
                    </div>
                  ) : (
                    opt.label
                  )}
                </div>
              );
            })
          )}
          {loadingMore && (
            <div className="px-3 py-2 text-center text-sm-regular text-gray-400">
              더 불러오는 중…
            </div>
          )}
        </div>
      )}

      <FeedbackMessage
        status={status}
        errorMessage={errorMessage}
        successMessage={successMessage}
        helperText={helperText}
        id={feedbackId}
      />
    </div>
  );
};

Select.displayName = 'Select';
